	VPBLENDVB Y9, Y7, Y4, Y4
	VPAND     Y13, Y6, Y6
	VPCMPEQB  Y15, Y6, Y6        // the borrow
	VPAND     K_B07, Y3, Y7
	VPADDB    K_D8, Y7, Y7
	VPADDB    Y6, Y7, Y7
	VPBLENDVB Y9, Y7, Y8, Y8
	// The low surrogate: DC00 | (b1 & 0F) << 6 | b0 & 3F.
	VPAND     K_B03, Y5, Y7
	VPOR      K_DC, Y7, Y7
	VPBLENDVB Y10, Y7, Y8, Y8

swpack:
	VPUNPCKLBW Y8, Y4, Y5        // the units of positions 0 to 7 and 16 to 23
	VPUNPCKHBW Y8, Y4, Y6        // 8 to 15 and 24 to 31
	MOVL      R8, R9
	ANDL      $0xff, R9
	MOVL      R8, R10
	SHRL      $8, R10
	ANDL      $0xff, R10
	MOVL      R8, R11
	SHRL      $16, R11
	ANDL      $0xff, R11
	MOVL      R8, R12
	SHRL      $24, R12
	LEAQ      ·wideShuf(SB), AX
	MOVL      R9, CX
	SHLL      $4, CX
	VMOVDQU   (AX)(CX*1), X7
	MOVL      R11, CX
	SHLL      $4, CX
	VINSERTI128 $1, (AX)(CX*1), Y7, Y7
	VPSHUFB   Y7, Y5, Y5
	MOVL      R10, CX
	SHLL      $4, CX
	VMOVDQU   (AX)(CX*1), X7
	MOVL      R12, CX
	SHLL      $4, CX
	VINSERTI128 $1, (AX)(CX*1), Y7, Y7
	VPSHUFB   Y7, Y6, Y6
	POPCNTL   R9, R9
	POPCNTL   R10, R10
	POPCNTL   R11, R11
	POPCNTL   R12, R12
	VMOVDQU   X5, (DI)
	LEAQ      (DI)(R9*2), DI
	VMOVDQU   X6, (DI)
	LEAQ      (DI)(R10*2), DI
	VEXTRACTI128 $1, Y5, X7
	VMOVDQU   X7, (DI)
	LEAQ      (DI)(R11*2), DI
	VEXTRACTI128 $1, Y6, X7
	VMOVDQU   X7, (DI)
	LEAQ      (DI)(R12*2), DI
	ADDQ      $32, DX
	JMP       swide

swideDone:
	VPSUBUSB K_TAIL, Y14, Y4
	VPOR     Y4, Y12, Y12
	VPTEST   Y12, Y12
	JNZ      sinvalid
	MOVQ     DI, AX
	SUBQ     wide-16(SP), AX
	SHRQ     $1, AX
	NOTQ     AX
	JMP      sdone

sinvalid:
	MOVQ $0x7fffffffffffffff, AX
	JMP  sdone

sdone:
	MOVQ AX, ret+32(FP)
	VZEROUPPER
	RET

// func wireStringsAVX2(dst unsafe.Pointer, room int, strs unsafe.Pointer, count int, ptrs bool) (done, written int)
//
// It writes strings from strs (count of them: strings, or pointers to them when ptrs, nil the null string) at dst
// (room bytes), each with its header, while each has room for 4+2*len+64 bytes and is WTF-8 of fewer than 2^30
// bytes; it returns how many it wrote and the bytes they took.
TEXT ·wireStringsAVX2(SB), NOSPLIT, $32-56
	MOVQ dst+0(FP), AX
	MOVQ AX, out-24(SP)
	ADDQ room+8(FP), AX
	MOVQ AX, end-32(SP)
	XORQ R14, R14           // the strings done (R14 is free in ABI0)
	VPXOR   Y15, Y15, Y15
	VMOVDQU K_NIB, Y11
	VMOVDQU K_C0, Y13

mnext:
	MOVQ R14, CX
	CMPQ CX, count+24(FP)
	JAE  mfinish
	MOVQ strs+16(FP), R8
	CMPB ptrs+32(FP), $0
	JEQ  mvalue
	MOVQ (R8)(CX*8), R8
	TESTQ R8, R8
	JNZ  mheader
	// nil: the null string.
	MOVQ out-24(SP), DI
	LEAQ 4(DI), AX
	CMPQ AX, end-32(SP)
	JA   mfinish
	MOVL $0xffffffff, (DI)
	MOVQ AX, out-24(SP)
	INCQ R14
	JMP  mnext

mvalue:
	SHLQ $4, CX
	ADDQ CX, R8

mheader:
	MOVQ (R8), SI
	MOVQ 8(R8), BX
	MOVQ out-24(SP), DI
	TESTQ BX, BX
	JNZ  mtext
	LEAQ 4(DI), AX
	CMPQ AX, end-32(SP)
	JA   mfinish
	MOVL $0, (DI)
	MOVQ AX, out-24(SP)
	INCQ R14
	JMP  mnext

mtext:
	CMPQ BX, $0x40000000
	JAE  mfinish
	LEAQ 68(DI)(BX*2), AX
	CMPQ AX, end-32(SP)
	JA   mfinish
	ADDQ $4, DI
	MOVQ DI, start-8(SP)
	MOVQ DI, wide-16(SP)
	XORQ    DX, DX
	VPXOR   Y14, Y14, Y14
	VPXOR   Y12, Y12, Y12

mlatin1:
	MOVQ BX, AX
	SUBQ DX, AX
	JLE  mlatin1Done
	MOVL    $0xffffffff, R13
	CMPQ    AX, $32
	JB      mltail
	VMOVDQU (SI)(DX*1), Y0
	JMP     mlbody

mltail:
	// Fewer than 32 bytes left: R13 the mask of those, the bytes past them zeros.
	MOVL    $1, R13
	MOVQ    AX, CX
	SHLL    CX, R13
	DECL    R13
	LEAQ    (SI)(DX*1), R8
	MOVL    R8, R9
	ANDL    $4095, R9
	CMPL    R9, $4064
	JA      mlcopy
	VMOVDQU (R8), Y0
	LEAQ    K_MASK, R10
	ADDQ    $32, R10
	SUBQ    AX, R10
	VPAND   (R10), Y0, Y0
	JMP     mlbody

mlcopy:
	// The 32 bytes from there cross into the next page: the bytes left are copied to where the output goes next
	// (room not written yet), then read from there.
	VPXOR   Y0, Y0, Y0
	VMOVDQU Y0, (DI)
	XORQ    R9, R9

mlbyte:
	MOVBLZX (R8)(R9*1), R10
	MOVB    R10, (DI)(R9*1)
	INCQ    R9
	CMPQ    R9, AX
	JB      mlbyte
	VMOVDQU (DI), Y0
	JMP     mlbody

mlbody:
	VPMOVMSKB Y0, R8
	TESTL     R8, R8
	JNZ       mlchars
	// ASCII: no char of the block before may be cut.
	VPSUBUSB  K_TAIL, Y14, Y4
	VPOR      Y4, Y12, Y12
	VMOVDQU   Y0, (DI)
	POPCNTL   R13, R8
	ADDQ      R8, DI
	VMOVDQA   Y0, Y14
	ADDQ      $32, DX
	JMP       mlatin1

mlchars:
	// A byte above C3 (a char above U+00FF, or not UTF-8): UTF-16, from the start.
	VPSUBUSB  K_C3, Y0, Y4
	VPTEST    Y4, Y4
	JNZ       mtoUTF16
	// Its bytes are ASCII, leads C2 and C3 and continuations: it is valid when the continuations are exactly the
	// bytes after the leads, and there are no C0 or C1.
	VPERM2I128 $0x21, Y0, Y14, Y1
	VPALIGNR  $15, Y1, Y0, Y2    // the byte before each
	VPAND     K_FE, Y0, Y7
	VPCMPEQB  K_C2, Y7, Y4       // the leads
	VPCMPEQB  Y13, Y7, Y7        // C0 and C1
	VPOR      Y7, Y12, Y12
	VPAND     K_FE, Y2, Y5
	VPCMPEQB  K_C2, Y5, Y5       // after a lead
	VPCMPGTB  Y0, Y13, Y6        // continuations
	VPXOR     Y6, Y5, Y5
	VPOR      Y5, Y12, Y12
	VPCMPEQB  K_C3, Y2, Y5
	VPAND     K_B40, Y5, Y5
	VPADDB    Y5, Y0, Y6         // the bytes: 40 more after C3
	VPMOVMSKB Y4, R8
	NOTL      R8
	ANDL      R13, R8            // kept
	MOVL      R8, R9
	ANDL      $0xff, R9
	MOVL      R8, R10
	SHRL      $8, R10
	ANDL      $0xff, R10
	MOVL      R8, R11
	SHRL      $16, R11
	ANDL      $0xff, R11
	MOVL      R8, R12
	SHRL      $24, R12
	LEAQ      ·narrowLo(SB), AX
	LEAQ      ·narrowHi(SB), CX
	VMOVQ     (AX)(R9*8), X4
	VPINSRQ   $1, (CX)(R10*8), X4, X4
	VMOVQ     (AX)(R11*8), X7
	VPINSRQ   $1, (CX)(R12*8), X7, X7
	VINSERTI128 $1, X7, Y4, Y4
	VPSHUFB   Y4, Y6, Y6
	POPCNTL   R9, R9
	POPCNTL   R10, R10
	POPCNTL   R11, R11
	POPCNTL   R12, R12
	VMOVDQU   X6, (DI)
	VPEXTRQ   $1, X6, CX
	MOVQ      CX, (DI)(R9*1)
	ADDQ      R9, DI
	ADDQ      R10, DI
	VEXTRACTI128 $1, Y6, X7
	VMOVDQU   X7, (DI)
	VPEXTRQ   $1, X7, CX
	MOVQ      CX, (DI)(R11*1)
	ADDQ      R11, DI
	ADDQ      R12, DI
	VMOVDQA   Y0, Y14
	ADDQ      $32, DX
	JMP       mlatin1

mlatin1Done:
	VPSUBUSB K_TAIL, Y14, Y4
	VPOR     Y4, Y12, Y12
	VPTEST   Y12, Y12
	JNZ      minvalid
	MOVQ     DI, AX
	SUBQ     start-8(SP), AX
	JMP      mdone

mtoUTF16:
	// From the start again, as UTF-16: the block in Y0 when it is the first.
	MOVQ  wide-16(SP), DI
	VPXOR Y14, Y14, Y14
	VPXOR Y12, Y12, Y12
	TESTQ DX, DX
	JZ    mwchars
	XORQ  DX, DX

mwide:
	MOVQ BX, AX
	SUBQ DX, AX
	JLE  mwideDone
	MOVL    $0xffffffff, R13
	CMPQ    AX, $32
	JB      mwtail
	VMOVDQU (SI)(DX*1), Y0
	JMP     mwbody

mwtail:
	// Fewer than 32 bytes left: R13 the mask of those, the bytes past them zeros.
	MOVL    $1, R13
	MOVQ    AX, CX
	SHLL    CX, R13
	DECL    R13
	LEAQ    (SI)(DX*1), R8
	MOVL    R8, R9
	ANDL    $4095, R9
	CMPL    R9, $4064
	JA      mwcopy
	VMOVDQU (R8), Y0
	LEAQ    K_MASK, R10
	ADDQ    $32, R10
	SUBQ    AX, R10
	VPAND   (R10), Y0, Y0
	JMP     mwbody

mwcopy:
	// The 32 bytes from there cross into the next page: the bytes left are copied to where the output goes next
	// (room not written yet), then read from there.
	VPXOR   Y0, Y0, Y0
	VMOVDQU Y0, (DI)
	XORQ    R9, R9

mwbyte:
	MOVBLZX (R8)(R9*1), R10
	MOVB    R10, (DI)(R9*1)
	INCQ    R9
	CMPQ    R9, AX
	JB      mwbyte
	VMOVDQU (DI), Y0
	JMP     mwbody

mwbody:
	VPMOVMSKB Y0, R8
	TESTL     R8, R8
	JNZ       mwchars
	VPSUBUSB  K_TAIL, Y14, Y4
	VPOR      Y4, Y12, Y12
	VPMOVZXBW X0, Y4
	VEXTRACTI128 $1, Y0, X5
	VPMOVZXBW X5, Y5
	VMOVDQU   Y4, (DI)
	VMOVDQU   Y5, 32(DI)
	POPCNTL   R13, R8
	LEAQ      (DI)(R8*2), DI
	VMOVDQA   Y0, Y14
	ADDQ      $32, DX
	JMP       mwide

mwchars:
	// Check the block (Keiser and Lemire): Y1 the byte three before each, Y2 one before, Y3 two before.
	VPERM2I128     $0x21, Y0, Y14, Y1
	VPALIGNR       $15, Y1, Y0, Y2
	VPALIGNR       $14, Y1, Y0, Y3
	VPALIGNR       $13, Y1, Y0, Y1
	VBROADCASTI128 K_T1, Y8
	VBROADCASTI128 K_T2, Y9
	VBROADCASTI128 K_T3, Y10
	VPSRLW         $4, Y2, Y4
	VPAND          Y11, Y4, Y4
	VPSHUFB        Y4, Y8, Y4
	VPAND          Y11, Y2, Y5
	VPSHUFB        Y5, Y9, Y5
	VPSRLW         $4, Y0, Y6
	VPAND          Y11, Y6, Y6
	VPSHUFB        Y6, Y10, Y6
	VPAND          Y5, Y4, Y4
	VPAND          Y6, Y4, Y4
	VPSUBUSB       K_S60, Y3, Y5
	VPSUBUSB       K_S70, Y1, Y6
	VPOR           Y6, Y5, Y5
	VPAND          K_B80, Y5, Y5
	VPXOR          Y5, Y4, Y4
	VPOR           Y4, Y12, Y12
	VMOVDQA   Y0, Y14
	VPCMPGTB  Y0, Y13, Y4        // b0 a continuation
	VPCMPGTB  Y2, Y13, Y5        // b1 a continuation
	VPAND     K_E0, Y2, Y6
	VPCMPEQB  Y13, Y6, Y6        // b1 the lead of 2 bytes
	VPCMPGTB  Y0, Y15, Y7        // b0 not ASCII
	VPOR      Y6, Y5, Y5
	VPAND     Y4, Y5, Y5         // b0 ends a char of 2 or more bytes, or is a third byte
	VPANDN    Y7, Y5, Y5         // dropped: the rest of the bytes not ASCII
	VPMOVMSKB Y5, R8
	NOTL      R8
	ANDL      R13, R8            // kept
	// The low bytes: b0 for ASCII, else (b0 & 3F) | b1 << 6.
	VPAND     K_B3F, Y0, Y4
	VPSLLW    $6, Y2, Y5
	VPAND     Y13, Y5, Y5
	VPOR      Y5, Y4, Y4
	VPBLENDVB Y7, Y4, Y0, Y4
	// The high bytes: 0 for ASCII, (b1 >> 2) & 0F after the lead of 2 bytes, and that | b2 << 4 else.
	VPSRLW    $2, Y2, Y5
	VPAND     Y11, Y5, Y5
	VPSLLW    $4, Y3, Y8
	VPAND     K_F0, Y8, Y8
	VPOR      Y5, Y8, Y8
	VPBLENDVB Y6, Y5, Y8, Y8
	VPAND     Y7, Y8, Y8
	// Surrogates: b2 the lead of 4 bytes (the high one), or b3 (the low one).
	VPAND     K_F8, Y3, Y9
	VPCMPEQB  K_F0, Y9, Y9
	VPAND     K_F8, Y1, Y10
	VPCMPEQB  K_F0, Y10, Y10
	VPOR      Y10, Y9, Y6
	VPTEST    Y6, Y6
	JZ        mwpack
	// The high surrogate: D800 + ((b2 & 7) << 8 | (b1 & 3F) << 2 | (b0 >> 4) & 3) - 40.
	VPAND     K_B3F, Y2, Y6
	VPSLLW    $2, Y6, Y6
	VPSRLW    $4, Y0, Y7
	VPAND     K_B03, Y7, Y7
	VPOR      Y7, Y6, Y6
	VPSUBB    K_B40, Y6, Y7
	VPBLENDVB Y9, Y7, Y4, Y4
	VPAND     Y13, Y6, Y6
	VPCMPEQB  Y15, Y6, Y6        // the borrow
	VPAND     K_B07, Y3, Y7
	VPADDB    K_D8, Y7, Y7
	VPADDB    Y6, Y7, Y7
	VPBLENDVB Y9, Y7, Y8, Y8
	// The low surrogate: DC00 | (b1 & 0F) << 6 | b0 & 3F.
	VPAND     K_B03, Y5, Y7
	VPOR      K_DC, Y7, Y7
	VPBLENDVB Y10, Y7, Y8, Y8

mwpack:
	VPUNPCKLBW Y8, Y4, Y5        // the units of positions 0 to 7 and 16 to 23
	VPUNPCKHBW Y8, Y4, Y6        // 8 to 15 and 24 to 31
	MOVL      R8, R9
	ANDL      $0xff, R9
	MOVL      R8, R10
	SHRL      $8, R10
	ANDL      $0xff, R10
	MOVL      R8, R11
	SHRL      $16, R11
	ANDL      $0xff, R11
	MOVL      R8, R12
	SHRL      $24, R12
	LEAQ      ·wideShuf(SB), AX
	MOVL      R9, CX
	SHLL      $4, CX
	VMOVDQU   (AX)(CX*1), X7
	MOVL      R11, CX
	SHLL      $4, CX
	VINSERTI128 $1, (AX)(CX*1), Y7, Y7
	VPSHUFB   Y7, Y5, Y5
	MOVL      R10, CX
	SHLL      $4, CX
	VMOVDQU   (AX)(CX*1), X7
	MOVL      R12, CX
	SHLL      $4, CX
	VINSERTI128 $1, (AX)(CX*1), Y7, Y7
	VPSHUFB   Y7, Y6, Y6
	POPCNTL   R9, R9
	POPCNTL   R10, R10
	POPCNTL   R11, R11
	POPCNTL   R12, R12
	VMOVDQU   X5, (DI)
	LEAQ      (DI)(R9*2), DI
	VMOVDQU   X6, (DI)
	LEAQ      (DI)(R10*2), DI
	VEXTRACTI128 $1, Y5, X7
	VMOVDQU   X7, (DI)
	LEAQ      (DI)(R11*2), DI
	VEXTRACTI128 $1, Y6, X7
	VMOVDQU   X7, (DI)
	LEAQ      (DI)(R12*2), DI
	ADDQ      $32, DX
	JMP       mwide

mwideDone:
	VPSUBUSB K_TAIL, Y14, Y4
	VPOR     Y4, Y12, Y12
	VPTEST   Y12, Y12
	JNZ      minvalid
	MOVQ     DI, AX
	SUBQ     wide-16(SP), AX
	SHRQ     $1, AX
	NOTQ     AX
	JMP      mdone

minvalid:
	MOVQ $0x7fffffffffffffff, AX
	JMP  mdone

mdone:
	MOVQ out-24(SP), DI
	MOVQ $0x7fffffffffffffff, CX
	CMPQ AX, CX
	JEQ  mfinish
	TESTQ AX, AX
	JS   mstore16
	MOVL AX, CX
	NOTL CX
	MOVL CX, (DI)
	LEAQ 4(DI)(AX*1), DI
	MOVQ DI, out-24(SP)
	INCQ R14
	JMP  mnext

mstore16:
	NOTQ AX
	MOVL AX, (DI)
	LEAQ 4(DI)(AX*2), DI
	MOVQ DI, out-24(SP)
	INCQ R14
	JMP  mnext

mfinish:
	MOVQ R14, AX
	MOVQ AX, done+40(FP)
	MOVQ out-24(SP), AX
	SUBQ dst+0(FP), AX
	MOVQ AX, written+48(FP)
	VZEROUPPER
	RET

// func wireStringAVX512(dst unsafe.Pointer, i int, src unsafe.Pointer, n int) int
TEXT ·wireStringAVX512(SB), NOSPLIT, $16-40
	MOVQ src+16(FP), SI
	MOVQ i+8(FP), DX
	ADDQ DX, SI              // the text from i on
	MOVQ n+24(FP), BX
	SUBQ DX, BX              // its length
	MOVQ dst+0(FP), DI
	LEAQ (DI)(DX*2), AX
	MOVQ AX, wide-16(SP)     // UTF-16 goes to dst+2*i
	ADDQ DX, DI              // Latin-1 to dst+i
	MOVQ DI, start-8(SP)
	VPXOR   Y15, Y15, Y15
	VMOVDQU K_NIB, Y11
	VMOVDQU K_C0, Y13
	VBROADCASTI32X4 K_T1, Y16
	VBROADCASTI32X4 K_T2, Y17
	VBROADCASTI32X4 K_T3, Y18
	XORQ    DX, DX
	VPXOR   Y14, Y14, Y14
	VPXOR   Y12, Y12, Y12
	XORL    R12, R12

tlatin1:
	MOVQ BX, AX
	SUBQ DX, AX
	JLE  tlatin1Done
	CMPQ    AX, $32
	JB      tltail
	MOVL    $0xffffffff, R13
	VMOVDQU (SI)(DX*1), Y0
	JMP     tlbody

tltail:
	// Fewer than 32 bytes left: R13 the mask of those, read alone (masked, so no fault past them).
	MOVL          $1, R13
	MOVQ          AX, CX
	SHLL          CX, R13
	DECL          R13
	KMOVD         R13, K1
	VMOVDQU8.Z    (SI)(DX*1), K1, Y0
	JMP           tlbody

tlbody:
	VPMOVMSKB Y0, R8
	TESTL     R8, R8
	JNZ       tlchars
	// ASCII: no char of the block before may be cut.
	TESTL     R12, R12
	JNZ       tinvalid
	VMOVDQU   Y0, (DI)
	POPCNTL   R13, R8
	ADDQ      R8, DI
	ADDQ      $32, DX
	JMP       tlatin1

tlchars:
	// A byte above C3 (a char above U+00FF, or not UTF-8): UTF-16, from the start.
	VPSUBUSB  K_C3, Y0, Y4
	VPTEST    Y4, Y4
	JNZ       ttoUTF16
	VPCMPGTB    Y0, Y13, K1        // continuations
	VPCMPEQB    K_C3, Y0, K2       // C3
	VPAND       K_FE, Y0, Y4
	VPCMPEQB    K_C2, Y4, K3       // the leads
	KMOVD       K1, R9
	KMOVD       K3, R10
	KMOVD       K2, R11
	MOVL        R12, AX
	ANDL        $1, AX
	LEAQ        (AX)(R10*2), AX
	XORL        R9, AX
	JNZ         tinvalid         // a lead without its continuation, or a continuation without its lead
	MOVL        R10, AX
	ORL         R9, AX
	NOTL        AX
	ANDL        R8, AX
	JNZ         tinvalid         // C0 or C1
	MOVL        R12, CX
	SHRL        $1, CX
	LEAQ        (CX)(R11*2), CX    // the bytes after C3
	KMOVD       CX, K4
	MOVL        R10, R12
	SHRL        $31, R12
	SHRL        $31, R11
	LEAL        (R12)(R11*2), R12
	VMOVDQA     Y0, Y6
	VPADDB      K_B40, Y0, K4, Y6  // the bytes: 40 more after C3
	NOTL        R10
	ANDL        R13, R10           // kept: all but the leads
	KMOVD       R10, K2
	VPCOMPRESSB Y6, K2, Y6
	VMOVDQU     Y6, (DI)
	POPCNTL     R10, R10
	ADDQ        R10, DI
	ADDQ        $32, DX
	JMP         tlatin1

tlatin1Done:
	TESTL    R12, R12
	JNZ      tinvalid
	MOVQ     DI, AX
	SUBQ     start-8(SP), AX
	JMP      tdone

ttoUTF16:
	// From the start again, as UTF-16: the block in Y0 when it is the first.
	MOVQ  wide-16(SP), DI
	VPXOR Y14, Y14, Y14
	VPXOR Y12, Y12, Y12
	TESTQ DX, DX
	JZ    twchars
	XORQ  DX, DX

twide:
	MOVQ BX, AX
	SUBQ DX, AX
	JLE  twideDone
	CMPQ    AX, $32
	JB      twtail
	MOVL    $0xffffffff, R13
	VMOVDQU (SI)(DX*1), Y0
	JMP     twbody

twtail:
	// Fewer than 32 bytes left: R13 the mask of those, read alone (masked, so no fault past them).
	MOVL          $1, R13
	MOVQ          AX, CX
	SHLL          CX, R13
	DECL          R13
	KMOVD         R13, K1
	VMOVDQU8.Z    (SI)(DX*1), K1, Y0
	JMP           twbody

twbody:
	VPMOVMSKB Y0, R8
	TESTL     R8, R8
	JNZ       twchars
	VPSUBUSB  K_TAIL, Y14, Y4
	VPOR      Y4, Y12, Y12
	VPMOVZXBW Y0, Z4
	VMOVDQU64 Z4, (DI)
	POPCNTL   R13, R8
	LEAQ      (DI)(R8*2), DI
	VMOVDQA   Y0, Y14
	ADDQ      $32, DX
	JMP       twide

twchars:
	// Check the block (Keiser and Lemire): Y1 the byte three before each, Y2 one before, Y3 two before.
	VPERM2I128     $0x21, Y0, Y14, Y1
	VPALIGNR       $15, Y1, Y0, Y2
	VPALIGNR       $14, Y1, Y0, Y3
	VPALIGNR       $13, Y1, Y0, Y1
	VPSRLW         $4, Y2, Y4
	VPAND          Y11, Y4, Y4
	VPSHUFB        Y4, Y16, Y4
	VPAND          Y11, Y2, Y5
	VPSHUFB        Y5, Y17, Y5
	VPSRLW         $4, Y0, Y6
	VPAND          Y11, Y6, Y6
	VPSHUFB        Y6, Y18, Y6
	VPAND          Y5, Y4, Y4
	VPAND          Y6, Y4, Y4
	VPSUBUSB       K_S60, Y3, Y5
	VPSUBUSB       K_S70, Y1, Y6
	VPOR           Y6, Y5, Y5
	VPAND          K_B80, Y5, Y5
	VPXOR          Y5, Y4, Y4
	VPOR           Y4, Y12, Y12
	VMOVDQA    Y0, Y14
	VPCMPGTB   Y0, Y13, K3        // b0 a continuation
	VPCMPGTB   Y2, Y13, K4        // b1 a continuation
	VPAND      K_E0, Y2, Y6
	VPCMPEQB   Y13, Y6, K6        // b1 the lead of 2 bytes
	VPMOVB2M   Y0, K7             // b0 not ASCII
	KORD       K6, K4, K4
	KANDD      K3, K4, K4         // b0 ends a char of 2 or more bytes, or is a third byte
	KNOTD      K7, K5
	KORD       K5, K4, K4         // kept: those and ASCII
	KMOVD      K4, R8
	ANDL       R13, R8
	// The low bytes: b0 for ASCII, else (b0 & 3F) | b1 << 6.
	VPAND      K_B3F, Y0, Y4
	VPSLLW     $6, Y2, Y5
	VPAND      Y13, Y5, Y5
	VPOR       Y5, Y4, Y4
	VPBLENDMB  Y4, Y0, K7, Y4
	// The high bytes: 0 for ASCII, (b1 >> 2) & 0F after the lead of 2 bytes, and that | b2 << 4 else.
	VPSRLW     $2, Y2, Y5
	VPAND      Y11, Y5, Y5
	VPSLLW     $4, Y3, Y8
	VPAND      K_F0, Y8, Y8
	VPOR       Y5, Y8, Y8
	VPBLENDMB  Y5, Y8, K6, Y8
	VMOVDQU8.Z Y8, K7, Y8
	// Surrogates: b2 the lead of 4 bytes (the high one), or b3 (the low one).
	VPAND      K_F8, Y3, Y9
	VPCMPEQB   K_F0, Y9, K1
	VPAND      K_F8, Y1, Y10
	VPCMPEQB   K_F0, Y10, K2
	KORTESTD   K1, K2
	JZ         twpack
	// The high surrogate: D800 + ((b2 & 7) << 8 | (b1 & 3F) << 2 | (b0 >> 4) & 3) - 40.
	VPAND      K_B3F, Y2, Y6
	VPSLLW     $2, Y6, Y6
	VPSRLW     $4, Y0, Y7
	VPAND      K_B03, Y7, Y7
	VPOR       Y7, Y6, Y6
	VPSUBB     K_B40, Y6, Y7
	VPBLENDMB  Y7, Y4, K1, Y4
	VPAND      Y13, Y6, Y6
	VPCMPEQB   Y15, Y6, Y6        // the borrow
	VPAND      K_B07, Y3, Y7
	VPADDB     K_D8, Y7, Y7
	VPADDB     Y6, Y7, Y7
	VPBLENDMB  Y7, Y8, K1, Y8
	// The low surrogate: DC00 | (b1 & 0F) << 6 | b0 & 3F.
	VPAND      K_B03, Y5, Y7
	VPOR       K_DC, Y7, Y7
	VPBLENDMB  Y7, Y8, K2, Y8

twpack:
	VPMOVZXBW   Y4, Z4
	VPMOVZXBW   Y8, Z5
	VPSLLW      $8, Z5, Z5
	VPORQ       Z5, Z4, Z4
	KMOVD       R8, K2
	VPCOMPRESSW Z4, K2, Z4
	VMOVDQU64   Z4, (DI)
	POPCNTL     R8, R8
	LEAQ        (DI)(R8*2), DI
	ADDQ        $32, DX
	JMP         twide

twideDone:
	VPSUBUSB K_TAIL, Y14, Y4
	VPOR     Y4, Y12, Y12
	VPTEST   Y12, Y12
	JNZ      tinvalid
	MOVQ     DI, AX
	SUBQ     wide-16(SP), AX
	SHRQ     $1, AX
	NOTQ     AX
	JMP      tdone

tinvalid:
	MOVQ $0x7fffffffffffffff, AX
	JMP  tdone

tdone:
	MOVQ AX, ret+32(FP)
	VZEROUPPER
	RET

// func wireStringsAVX512(dst unsafe.Pointer, room int, strs unsafe.Pointer, count int, ptrs bool) (done, written int)
//
// It writes strings from strs (count of them: strings, or pointers to them when ptrs, nil the null string) at dst
// (room bytes), each with its header, while each has room for 4+2*len+64 bytes and is WTF-8 of fewer than 2^30
// bytes; it returns how many it wrote and the bytes they took.
TEXT ·wireStringsAVX512(SB), NOSPLIT, $32-56
	MOVQ dst+0(FP), AX
	MOVQ AX, out-24(SP)
	ADDQ room+8(FP), AX
	MOVQ AX, end-32(SP)
	XORQ R14, R14           // the strings done (R14 is free in ABI0)
	VPXOR   Y15, Y15, Y15
	VMOVDQU K_NIB, Y11
	VMOVDQU K_C0, Y13
	VBROADCASTI32X4 K_T1, Y16
	VBROADCASTI32X4 K_T2, Y17
	VBROADCASTI32X4 K_T3, Y18

nnext:
	MOVQ R14, CX
	CMPQ CX, count+24(FP)
	JAE  nfinish
	MOVQ strs+16(FP), R8
	CMPB ptrs+32(FP), $0
	JEQ  nvalue
	MOVQ (R8)(CX*8), R8
	TESTQ R8, R8
	JNZ  nheader
	// nil: the null string.
	MOVQ out-24(SP), DI
	LEAQ 4(DI), AX
	CMPQ AX, end-32(SP)
	JA   nfinish
	MOVL $0xffffffff, (DI)
	MOVQ AX, out-24(SP)
	INCQ R14
	JMP  nnext

nvalue:
	SHLQ $4, CX
	ADDQ CX, R8

nheader:
	MOVQ (R8), SI
	MOVQ 8(R8), BX
	MOVQ out-24(SP), DI
	TESTQ BX, BX
	JNZ  ntext
	LEAQ 4(DI), AX
	CMPQ AX, end-32(SP)
	JA   nfinish
	MOVL $0, (DI)
	MOVQ AX, out-24(SP)
	INCQ R14
	JMP  nnext

ntext:
	CMPQ BX, $0x40000000
	JAE  nfinish
	LEAQ 68(DI)(BX*2), AX
	CMPQ AX, end-32(SP)
	JA   nfinish
	ADDQ $4, DI
	MOVQ DI, start-8(SP)
	MOVQ DI, wide-16(SP)
	XORQ    DX, DX
	VPXOR   Y14, Y14, Y14
	VPXOR   Y12, Y12, Y12
	XORL    R12, R12

nlatin1:
	MOVQ BX, AX
	SUBQ DX, AX
	JLE  nlatin1Done
	CMPQ    AX, $32
	JB      nltail
	MOVL    $0xffffffff, R13
	VMOVDQU (SI)(DX*1), Y0
	JMP     nlbody

nltail:
	// Fewer than 32 bytes left: R13 the mask of those, read alone (masked, so no fault past them).
	MOVL          $1, R13
	MOVQ          AX, CX
	SHLL          CX, R13
	DECL          R13
	KMOVD         R13, K1
	VMOVDQU8.Z    (SI)(DX*1), K1, Y0
	JMP           nlbody

nlbody:
	VPMOVMSKB Y0, R8
	TESTL     R8, R8
	JNZ       nlchars
	// ASCII: no char of the block before may be cut.
	TESTL     R12, R12
	JNZ       ninvalid
	VMOVDQU   Y0, (DI)
	POPCNTL   R13, R8
	ADDQ      R8, DI
	ADDQ      $32, DX
	JMP       nlatin1

nlchars:
	// A byte above C3 (a char above U+00FF, or not UTF-8): UTF-16, from the start.
	VPSUBUSB  K_C3, Y0, Y4
	VPTEST    Y4, Y4
	JNZ       ntoUTF16
	VPCMPGTB    Y0, Y13, K1        // continuations
	VPCMPEQB    K_C3, Y0, K2       // C3
	VPAND       K_FE, Y0, Y4
	VPCMPEQB    K_C2, Y4, K3       // the leads
	KMOVD       K1, R9
	KMOVD       K3, R10
	KMOVD       K2, R11
	MOVL        R12, AX
	ANDL        $1, AX
	LEAQ        (AX)(R10*2), AX
	XORL        R9, AX
	JNZ         ninvalid         // a lead without its continuation, or a continuation without its lead
	MOVL        R10, AX
	ORL         R9, AX
	NOTL        AX
	ANDL        R8, AX
	JNZ         ninvalid         // C0 or C1
	MOVL        R12, CX
	SHRL        $1, CX
	LEAQ        (CX)(R11*2), CX    // the bytes after C3
	KMOVD       CX, K4
	MOVL        R10, R12
	SHRL        $31, R12
	SHRL        $31, R11
	LEAL        (R12)(R11*2), R12
	VMOVDQA     Y0, Y6
	VPADDB      K_B40, Y0, K4, Y6  // the bytes: 40 more after C3
	NOTL        R10
	ANDL        R13, R10           // kept: all but the leads
	KMOVD       R10, K2
	VPCOMPRESSB Y6, K2, Y6
	VMOVDQU     Y6, (DI)
	POPCNTL     R10, R10
	ADDQ        R10, DI
	ADDQ        $32, DX
	JMP         nlatin1

nlatin1Done:
	TESTL    R12, R12
	JNZ      ninvalid
	MOVQ     DI, AX
	SUBQ     start-8(SP), AX
	JMP      ndone

ntoUTF16:
	// From the start again, as UTF-16: the block in Y0 when it is the first.
	MOVQ  wide-16(SP), DI
	VPXOR Y14, Y14, Y14
	VPXOR Y12, Y12, Y12
	TESTQ DX, DX
	JZ    nwchars
	XORQ  DX, DX

nwide:
	MOVQ BX, AX
	SUBQ DX, AX
	JLE  nwideDone
	CMPQ    AX, $32
	JB      nwtail
	MOVL    $0xffffffff, R13
	VMOVDQU (SI)(DX*1), Y0
	JMP     nwbody

nwtail:
	// Fewer than 32 bytes left: R13 the mask of those, read alone (masked, so no fault past them).
	MOVL          $1, R13
	MOVQ          AX, CX
	SHLL          CX, R13
	DECL          R13
	KMOVD         R13, K1
	VMOVDQU8.Z    (SI)(DX*1), K1, Y0
	JMP           nwbody

nwbody:
	VPMOVMSKB Y0, R8
	TESTL     R8, R8
	JNZ       nwchars
	VPSUBUSB  K_TAIL, Y14, Y4
	VPOR      Y4, Y12, Y12
	VPMOVZXBW Y0, Z4
	VMOVDQU64 Z4, (DI)
	POPCNTL   R13, R8
	LEAQ      (DI)(R8*2), DI
	VMOVDQA   Y0, Y14
	ADDQ      $32, DX
	JMP       nwide

nwchars:
	// Check the block (Keiser and Lemire): Y1 the byte three before each, Y2 one before, Y3 two before.
	VPERM2I128     $0x21, Y0, Y14, Y1
	VPALIGNR       $15, Y1, Y0, Y2
	VPALIGNR       $14, Y1, Y0, Y3
	VPALIGNR       $13, Y1, Y0, Y1
	VPSRLW         $4, Y2, Y4
	VPAND          Y11, Y4, Y4
	VPSHUFB        Y4, Y16, Y4
	VPAND          Y11, Y2, Y5
	VPSHUFB        Y5, Y17, Y5
	VPSRLW         $4, Y0, Y6
	VPAND          Y11, Y6, Y6
	VPSHUFB        Y6, Y18, Y6
	VPAND          Y5, Y4, Y4
	VPAND          Y6, Y4, Y4
	VPSUBUSB       K_S60, Y3, Y5
	VPSUBUSB       K_S70, Y1, Y6
	VPOR           Y6, Y5, Y5
	VPAND          K_B80, Y5, Y5
	VPXOR          Y5, Y4, Y4
	VPOR           Y4, Y12, Y12
	VMOVDQA    Y0, Y14
	VPCMPGTB   Y0, Y13, K3        // b0 a continuation
	VPCMPGTB   Y2, Y13, K4        // b1 a continuation
	VPAND      K_E0, Y2, Y6
	VPCMPEQB   Y13, Y6, K6        // b1 the lead of 2 bytes
	VPMOVB2M   Y0, K7             // b0 not ASCII
	KORD       K6, K4, K4
	KANDD      K3, K4, K4         // b0 ends a char of 2 or more bytes, or is a third byte
	KNOTD      K7, K5
	KORD       K5, K4, K4         // kept: those and ASCII
	KMOVD      K4, R8
	ANDL       R13, R8
	// The low bytes: b0 for ASCII, else (b0 & 3F) | b1 << 6.
	VPAND      K_B3F, Y0, Y4
	VPSLLW     $6, Y2, Y5
	VPAND      Y13, Y5, Y5
	VPOR       Y5, Y4, Y4
	VPBLENDMB  Y4, Y0, K7, Y4
	// The high bytes: 0 for ASCII, (b1 >> 2) & 0F after the lead of 2 bytes, and that | b2 << 4 else.
	VPSRLW     $2, Y2, Y5
	VPAND      Y11, Y5, Y5
	VPSLLW     $4, Y3, Y8
	VPAND      K_F0, Y8, Y8
	VPOR       Y5, Y8, Y8
	VPBLENDMB  Y5, Y8, K6, Y8
	VMOVDQU8.Z Y8, K7, Y8
	// Surrogates: b2 the lead of 4 bytes (the high one), or b3 (the low one).
	VPAND      K_F8, Y3, Y9
	VPCMPEQB   K_F0, Y9, K1
	VPAND      K_F8, Y1, Y10
	VPCMPEQB   K_F0, Y10, K2
	KORTESTD   K1, K2
	JZ         nwpack
	// The high surrogate: D800 + ((b2 & 7) << 8 | (b1 & 3F) << 2 | (b0 >> 4) & 3) - 40.
	VPAND      K_B3F, Y2, Y6
	VPSLLW     $2, Y6, Y6
	VPSRLW     $4, Y0, Y7
	VPAND      K_B03, Y7, Y7
	VPOR       Y7, Y6, Y6
	VPSUBB     K_B40, Y6, Y7
	VPBLENDMB  Y7, Y4, K1, Y4
	VPAND      Y13, Y6, Y6
	VPCMPEQB   Y15, Y6, Y6        // the borrow
	VPAND      K_B07, Y3, Y7
	VPADDB     K_D8, Y7, Y7
	VPADDB     Y6, Y7, Y7
	VPBLENDMB  Y7, Y8, K1, Y8
	// The low surrogate: DC00 | (b1 & 0F) << 6 | b0 & 3F.
	VPAND      K_B03, Y5, Y7
	VPOR       K_DC, Y7, Y7
	VPBLENDMB  Y7, Y8, K2, Y8

nwpack:
	VPMOVZXBW   Y4, Z4
	VPMOVZXBW   Y8, Z5
	VPSLLW      $8, Z5, Z5
	VPORQ       Z5, Z4, Z4
	KMOVD       R8, K2
	VPCOMPRESSW Z4, K2, Z4
	VMOVDQU64   Z4, (DI)
	POPCNTL     R8, R8
	LEAQ        (DI)(R8*2), DI
	ADDQ        $32, DX
	JMP         nwide

nwideDone:
	VPSUBUSB K_TAIL, Y14, Y4
	VPOR     Y4, Y12, Y12
	VPTEST   Y12, Y12
	JNZ      ninvalid
	MOVQ     DI, AX
	SUBQ     wide-16(SP), AX
	SHRQ     $1, AX
	NOTQ     AX
	JMP      ndone

ninvalid:
	MOVQ $0x7fffffffffffffff, AX
	JMP  ndone

ndone:
	MOVQ out-24(SP), DI
	MOVQ $0x7fffffffffffffff, CX
	CMPQ AX, CX
	JEQ  nfinish
	TESTQ AX, AX
	JS   nstore16
	MOVL AX, CX
	NOTL CX
	MOVL CX, (DI)
	LEAQ 4(DI)(AX*1), DI
	MOVQ DI, out-24(SP)
	INCQ R14
	JMP  nnext

nstore16:
	NOTQ AX
	MOVL AX, (DI)
	LEAQ 4(DI)(AX*2), DI
	MOVQ DI, out-24(SP)
	INCQ R14
	JMP  nnext

nfinish:
	MOVQ R14, AX
	MOVQ AX, done+40(FP)
	MOVQ out-24(SP), AX
	SUBQ dst+0(FP), AX
	MOVQ AX, written+48(FP)
	VZEROUPPER
	RET

// func utf16UTF8AVX512(dst, src unsafe.Pointer, units int) int
//
// It writes units UTF-16 code units (little-endian) at src as WTF-8 at dst (room for 3*units+64 bytes) and returns
// the bytes written. Each block of 16 units is widened to 16 lanes of 32 bits, each lane given the code point c
// (of the pair, for a high surrogate followed by a low one) and its UTF-8 in full 4-byte form, shifted down to its
// length (0 for the low surrogate of a pair), and the bytes kept compressed to the front.
TEXT ·utf16UTF8AVX512(SB), NOSPLIT, $0-32
	MOVQ           dst+0(FP), DI
	MOVQ           src+8(FP), SI
	MOVQ           units+16(FP), BX
	MOVQ           DI, R11
	MOVL           $0xFC00, AX
	VPBROADCASTD   AX, Z20
	MOVL           $0xD800, AX
	VPBROADCASTD   AX, Z21
	MOVL           $0xDC00, AX
	VPBROADCASTD   AX, Z22
	MOVL           $0x80, AX
	VPBROADCASTD   AX, Z23
	MOVL           $0x800, AX
	VPBROADCASTD   AX, Z24
	MOVL           $-0x35FDC00, AX   // 0x10000 - (D800 << 10) - DC00
	VPBROADCASTD   AX, Z25
	MOVQ           $0x20262C3200060C12, AX   // the bits of each byte: c >> 18, 12, 6 and 0, in both lanes of 64
	VPBROADCASTQ   AX, Z26
	MOVL           $0x3F3F3F07, AX
	VPBROADCASTD   AX, Z27
	MOVL           $0x808080F0, AX
	VPBROADCASTD   AX, Z28
	MOVL           $24, AX
	VPBROADCASTD   AX, Z29
	MOVL           $8, AX
	VPBROADCASTD   AX, Z30
	MOVL           $32, AX
	VPBROADCASTD   AX, Z19
	MOVL           $0x40, AX
	VPBROADCASTD   AX, Z18
	MOVL           $0x20, AX
	VPBROADCASTD   AX, Z17
	VPTERNLOGD     $0xFF, Z31, Z31, Z31
	XORQ           DX, DX

u16next:
	MOVQ           BX, CX
	SUBQ           DX, CX            // the units left
	JLE            u16done
	MOVL           $0xFFFF, R8
	CMPQ           CX, $16
	JAE            u16full
	MOVL           $1, R8
	SHLL           CX, R8
	DECL           R8

u16full:
	// R8 the units of the block, R9 the units after each, R10 the units before each (none before the first).
	MOVL           R8, R9
	SHRL           $1, R9
	CMPQ           CX, $17
	JB             u16after
	MOVL           $0xFFFF, R9

u16after:
	MOVL           R8, R10
	TESTQ          DX, DX
	JNZ            u16before
	ANDL           $0xFFFE, R10

u16before:
	KMOVW          R8, K1
	KMOVW          R9, K2
	KMOVW          R10, K3
	VMOVDQU16.Z    (SI)(DX*2), K1, Y0
	VMOVDQU16.Z    2(SI)(DX*2), K2, Y1
	VMOVDQU16.Z    -2(SI)(DX*2), K3, Y2
	VPMOVZXWD      Y0, Z0            // the units
	VPMOVZXWD      Y1, Z1            // the unit after each
	VPMOVZXWD      Y2, Z2            // the unit before each
	VPANDD         Z20, Z0, Z3
	VPCMPEQD       Z21, Z3, K4       // high surrogates
	VPCMPEQD       Z22, Z3, K6       // low surrogates
	VPANDD         Z20, Z1, Z3
	VPCMPEQD       Z22, Z3, K5
	VPANDD         Z20, Z2, Z3
	VPCMPEQD       Z21, Z3, K7
	KANDW          K5, K4, K4        // a high surrogate followed by a low one: the pair's 4 bytes
	KANDW          K7, K6, K6        // a low surrogate after a high one: no bytes
	VPSLLD         $10, Z0, Z3
	VPADDD         Z1, Z3, Z3
	VPADDD         Z25, Z3, Z3
	VMOVDQA32      Z3, K4, Z0        // c
	VPMULTISHIFTQB Z0, Z26, Z4
	VPTERNLOGD     $0xEA, Z28, Z27, Z4   // F0 | c >> 18, 80 | c >> 12 & 3F, 80 | c >> 6 & 3F, 80 | c & 3F
	VPCMPUD        $5, Z23, Z0, K2   // c >= 80
	VPCMPUD        $5, Z24, Z0, K3   // c >= 800
	VMOVDQA32      Z29, Z5
	VPSUBD         Z30, Z5, K2, Z5
	VPSUBD         Z30, Z5, K3, Z5
	VPSUBD         Z30, Z5, K4, Z5
	VMOVDQA32      Z19, K6, Z5       // the bits to drop: 8 for each byte short of 4
	VPSRLVD        Z5, Z4, Z4
	VPORD          Z18, Z4, K2, Z4   // the lead of 2 bytes: C0
	VPORD          Z17, Z4, K3, Z4   // of 3: E0 (of 4: F0 already)
	KNOTW          K2, K5
	VMOVDQA32      Z0, K5, Z4        // ASCII: c
	VPSRLVD        Z5, Z31, Z6
	VMOVDQA32.Z    Z6, K1, Z6
	VPTESTMB       Z6, Z6, K7        // the bytes kept
	VPCOMPRESSB    Z4, K7, Z4
	VMOVDQU64      Z4, (DI)
	KMOVQ          K7, AX
	POPCNTQ        AX, AX
	ADDQ           AX, DI
	ADDQ           $16, DX
	JMP            u16next

u16done:
	SUBQ           R11, DI
	MOVQ           DI, ret+24(FP)
	VZEROUPPER
	RET

// func latin1UTF8AVX512(dst, src unsafe.Pointer, n int) int
//
// It writes n Latin-1 bytes at src as UTF-8 at dst (room for 2*n+64 bytes) and returns the bytes written: each
// block of 32 widened to 16-bit lanes, a byte of 80 or above given its two bytes, and the bytes kept compressed to
// the front.
TEXT ·latin1UTF8AVX512(SB), NOSPLIT, $0-32
	MOVQ           dst+0(FP), DI
	MOVQ           src+8(FP), SI
	MOVQ           n+16(FP), BX
	MOVQ           DI, R11
	MOVL           $0x3F00, AX
	VPBROADCASTW   AX, Z20
	MOVL           $0x80C0, AX
	VPBROADCASTW   AX, Z21
	MOVQ           $0x5555555555555555, R12
	XORQ           DX, DX

l1next:
	MOVQ           BX, CX
	SUBQ           DX, CX            // the bytes left
	JLE            l1done
	MOVL           $0xFFFFFFFF, R8
	MOVQ           R12, R9
	CMPQ           CX, $32
	JAE            l1full
	MOVL           $1, R8
	SHLL           CX, R8
	DECL           R8
	ADDQ           CX, CX
	MOVQ           $1, R10
	SHLQ           CX, R10
	DECQ           R10
	ANDQ           R10, R9

l1full:
	// R8 the bytes of the block, R9 the low byte of each of their lanes.
	KMOVD          R8, K1
	VMOVDQU8.Z     (SI)(DX*1), K1, Y0
	VPMOVB2M       Y0, K2            // 80 or above
	VPMOVZXBW      Y0, Z0
	VPSRLW         $6, Z0, Z1
	VPSLLW         $8, Z0, Z2
	VPANDD         Z20, Z2, Z2
	VPTERNLOGD     $0xFE, Z21, Z2, Z1   // C0 | c >> 6, 80 | c & 3F
	VMOVDQU16      Z1, K2, Z0
	VPMOVB2M       Z0, K3            // the second byte of those (and their first)
	KMOVQ          K3, AX
	ORQ            R9, AX
	KMOVQ          AX, K3
	VPCOMPRESSB    Z0, K3, Z0
	VMOVDQU64      Z0, (DI)
	POPCNTQ        AX, AX
	ADDQ           AX, DI
	ADDQ           $32, DX
	JMP            l1next

l1done:
	SUBQ           R11, DI
	MOVQ           DI, ret+24(FP)
	VZEROUPPER
	RET

// func latin1UTF8SSE(dst, src unsafe.Pointer, n int) int
//
// It writes n Latin-1 bytes at src as UTF-8 at dst (room for 2*n+16 bytes) and returns the bytes written, as
// latin1UTF8NEON.
TEXT ·latin1UTF8SSE(SB), NOSPLIT, $0-32
	MOVQ    dst+0(FP), DI
	MOVQ    src+8(FP), SI
	MOVQ    n+16(FP), BX
	MOVQ    DI, R11
	XORQ    DX, DX
	LEAQ    ·pairShuf(SB), R8
	LEAQ    ·pairLen(SB), R9
	MOVOU   K_B03, X13
	MOVOU   K_C0, X14
	MOVOU   K_B40, X15

l1loop:
	MOVQ    BX, CX
	SUBQ    DX, CX                  // the bytes left
	JLE     l1done
	LEAQ    (SI)(DX*1), R10
	CMPQ    CX, $16
	JB      l1tail
	MOVOU   (R10), X0

l1body:
	PMOVMSKB X0, AX
	TESTL   AX, AX
	JNZ     l1high
	MOVOU   X0, (DI)
	ADDQ    $16, DI
	ADDQ    $16, DX
	JMP     l1loop

l1high:
	MOVOA   X0, X1
	PSRLW   $6, X1
	PAND    X13, X1
	POR     X14, X1                 // the leads: C0 | c >> 6
	PXOR    X2, X2
	PCMPGTB X0, X2
	PAND    X15, X2
	PANDN   X0, X2                  // the bytes after them: c, less 40 for 80 and above
	MOVOA   X1, X3
	PUNPCKLBW X2, X3                // the pairs of bytes 0 to 7
	PUNPCKHBW X2, X1                // of 8 to 15
	MOVL    AX, CX
	ANDL    $0xff, CX
	SHRL    $8, AX
	MOVQ    CX, R12
	SHLQ    $4, R12
	MOVOU   (R8)(R12*1), X4
	PSHUFB  X4, X3
	MOVQ    AX, R12
	SHLQ    $4, R12
	MOVOU   (R8)(R12*1), X5
	PSHUFB  X5, X1
	MOVBLZX (R9)(CX*1), R12
	MOVBLZX (R9)(AX*1), R13
	MOVOU   X3, (DI)
	ADDQ    R12, DI
	MOVOU   X1, (DI)
	ADDQ    R13, DI
	ADDQ    $16, DX
	JMP     l1loop

l1tail:
	MOVQ    CX, R12
	SHLQ    $0, R12           // the bytes left
	MOVL    R10, R13
	ANDL    $4095, R13
	CMPL    R13, $4080
	JA      l1cross
	MOVOU   (R10), X0
	LEAQ    K_MASK, R13
	ADDQ    $32, R13
	SUBQ    R12, R13
	MOVOU   (R13), X1
	PAND    X1, X0
	JMP     l1body

l1cross:
	PXOR    X0, X0
	MOVOU   X0, (DI)
	XORQ    R13, R13

l1byte:
	MOVBLZX (R10)(R13*1), AX
	MOVB    AX, (DI)(R13*1)
	INCQ    R13
	CMPQ    R13, R12
	JB      l1byte
	MOVOU   (DI), X0
	JMP     l1body

l1done:
	SUBQ    BX, DX                  // the zeros past the text
	SUBQ    DX, DI
	SUBQ    R11, DI
	MOVQ    DI, ret+24(FP)
	RET

// func utf16UTF8SSE(dst, src unsafe.Pointer, units int) int
//
// It writes units UTF-16 code units at src as WTF-8 at dst (room for 3*units+16 bytes) and returns the bytes
// written, as utf16UTF8NEON.
TEXT ·utf16UTF8SSE(SB), NOSPLIT, $0-32
	MOVQ    dst+0(FP), DI
	MOVQ    src+8(FP), SI
	MOVQ    units+16(FP), BX
	MOVQ    DI, R11
	XORQ    DX, DX
	PXOR    X7, X7
	MOVOU   K_WFF80, X8
	MOVOU   K_WF800, X9
	MOVOU   K_W3F, X10
	MOVOU   K_W80, X11
	MOVOU   K_WC0, X12
	MOVOU   K_WE0, X13
	MOVOU   K_W40, X14
	MOVOU   K_WFC00, X15

u16loop:
	MOVQ    BX, CX
	SUBQ    DX, CX                  // the units left
	JLE     u16done
	LEAQ    (SI)(DX*2), R10
	CMPQ    CX, $8
	JB      u16tail
	MOVOU   (R10), X0

u16body:
	MOVOA   X0, X1
	PAND    X8, X1
	PCMPEQW X7, X1                  // ASCII
	PMOVMSKB X1, AX
	CMPL    AX, $0xffff
	JNE     u16wide
	PACKUSWB X0, X0
	MOVQ    X0, (DI)
	ADDQ    $8, DI
	ADDQ    $8, DX
	JMP     u16loop

u16wide:
	MOVOA   X0, X3
	PAND    X9, X3
	PCMPEQW X7, X3                  // below 800
	PMOVMSKB X3, CX
	MOVOA   X1, X6
	PACKSSWB X6, X6
	PMOVMSKB X6, R13
	NOTL    R13
	ANDL    $0xff, R13              // not ASCII, a bit a unit
	// The last byte of each: the unit for ASCII, else 80 | u & 3F.
	MOVOA   X0, X4
	PAND    X10, X4
	POR     X11, X4
	MOVOA   X1, X5
	PAND    X0, X5
	PANDN   X4, X1
	POR     X5, X1
	CMPL    CX, $0xffff
	JNE     u16three
	// Each below 800: its lead C0 | u >> 6 and the last byte, as a pair.
	MOVOA   X0, X2
	PSRLW   $6, X2
	POR     X12, X2
	PSLLW   $8, X1
	POR     X1, X2
	MOVQ    R13, R12
	SHLQ    $4, R12
	LEAQ    ·pairShuf(SB), R14
	MOVOU   (R14)(R12*1), X4
	PSHUFB  X4, X2
	MOVOU   X2, (DI)
	LEAQ    ·pairLen(SB), R14
	MOVBLZX (R14)(R13*1), R12
	ADDQ    R12, DI
	ADDQ    $8, DX
	JMP     u16loop

u16three:
	// Each as 4 bytes: E0 | u >> 12, 80 | (u >> 6) & 3F (C0 | u >> 6 below 800), the last byte, 0.
	MOVOA   X0, X2
	PSRLW   $12, X2
	POR     X13, X2
	MOVOA   X0, X4
	PSRLW   $6, X4
	PAND    X10, X4
	POR     X11, X4
	PAND    X14, X3
	POR     X3, X4
	PSLLW   $8, X4
	POR     X4, X2
	MOVOA   X2, X4
	PUNPCKLWL X1, X2                // units 0 to 3
	PUNPCKHWL X1, X4                // 4 to 7
	// Two bits a unit: 0 for 1 byte, 1 for 2, 3 for 3 (2: none).
	NOTL    AX
	ANDL    $0x5555, AX
	NOTL    CX
	ANDL    $0xaaaa, CX
	ORL     CX, AX
	// High surrogates.
	MOVOU   K_WD800, X6
	MOVOA   X0, X5
	PAND    X15, X5
	PCMPEQW X6, X5
	PMOVMSKB X5, R13
	MOVQ    $8, R14                 // the units taken
	TESTL   R13, R13
	JNZ     u16cut

u16emit:
	MOVL    AX, CX
	ANDL    $0xff, CX
	SHRL    $8, AX
	LEAQ    ·u3Shuf(SB), R15
	MOVQ    CX, R12
	SHLQ    $4, R12
	MOVOU   (R15)(R12*1), X5
	PSHUFB  X5, X2
	MOVQ    AX, R12
	SHLQ    $4, R12
	MOVOU   (R15)(R12*1), X6
	PSHUFB  X6, X4
	LEAQ    ·u3Len(SB), R15
	MOVBLZX (R15)(CX*1), R12
	MOVBLZX (R15)(AX*1), R13
	MOVOU   X2, (DI)
	ADDQ    R12, DI
	MOVOU   X4, (DI)
	ADDQ    R13, DI
	ADDQ    R14, DX
	CMPQ    R14, $8
	JNE     u16surrogate
	JMP     u16loop

u16cut:
	// The units before the first high surrogate (k of them) only.
	BSFL    R13, CX                 // 2k
	MOVL    CX, R14
	SHRL    $1, R14
	MOVL    $1, R12
	SHLL    CX, R12
	DECL    R12                     // the bits of the units kept
	ANDL    R12, AX
	NOTL    R12
	ANDL    $0xaaaa, R12
	ORL     R12, AX
	JMP     u16emit

u16surrogate:
	// A high surrogate at DX: with the low one after it, 4 bytes; else alone, 3.
	MOVWLZX (SI)(DX*2), AX
	LEAQ    1(DX), R12
	CMPQ    R12, BX
	JAE     u16lone
	MOVWLZX 2(SI)(DX*2), CX
	MOVL    CX, R12
	ANDL    $0xFC00, R12
	CMPL    R12, $0xDC00
	JNE     u16lone
	SHLL    $10, AX
	ADDL    CX, AX
	SUBL    $0x35FDC00, AX          // the code point: (hi << 10) + lo + 10000 - (D800 << 10) - DC00
	MOVL    AX, CX
	SHRL    $18, CX
	ORL     $0xF0, CX
	MOVL    AX, R12
	SHRL    $12, R12
	ANDL    $0x3F, R12
	ORL     $0x80, R12
	SHLL    $8, R12
	ORL     R12, CX
	MOVL    AX, R12
	SHRL    $6, R12
	ANDL    $0x3F, R12
	ORL     $0x80, R12
	SHLL    $16, R12
	ORL     R12, CX
	ANDL    $0x3F, AX
	ORL     $0x80, AX
	SHLL    $24, AX
	ORL     AX, CX
	MOVL    CX, (DI)
	ADDQ    $4, DI
	ADDQ    $2, DX
	JMP     u16loop

u16lone:
	MOVL    AX, CX
	SHRL    $12, CX
	ORL     $0xE0, CX
	MOVL    AX, R12
	SHRL    $6, R12
	ANDL    $0x3F, R12
	ORL     $0x80, R12
	SHLL    $8, R12
	ORL     R12, CX
	ANDL    $0x3F, AX
	ORL     $0x80, AX
	SHLL    $16, AX
	ORL     AX, CX
	MOVL    CX, (DI)
	ADDQ    $3, DI
	INCQ    DX
	JMP     u16loop

u16tail:
	MOVQ    CX, R12
	SHLQ    $1, R12           // the bytes left
	MOVL    R10, R13
	ANDL    $4095, R13
	CMPL    R13, $4080
	JA      u16cross
	MOVOU   (R10), X0
	LEAQ    K_MASK, R13
	ADDQ    $32, R13
	SUBQ    R12, R13
	MOVOU   (R13), X1
	PAND    X1, X0
	JMP     u16body

u16cross:
	PXOR    X0, X0
	MOVOU   X0, (DI)
	XORQ    R13, R13

u16byte:
	MOVBLZX (R10)(R13*1), AX
	MOVB    AX, (DI)(R13*1)
	INCQ    R13
	CMPQ    R13, R12
	JB      u16byte
	MOVOU   (DI), X0
	JMP     u16body

u16done:
	SUBQ    BX, DX                  // the zero units past the text
	SUBQ    DX, DI
	SUBQ    R11, DI
	MOVQ    DI, ret+24(FP)
	RET

// func cpuid(eaxArg, ecxArg uint32) (eax, ebx, ecx, edx uint32)
TEXT ·cpuid(SB), NOSPLIT, $0-24
	MOVL eaxArg+0(FP), AX
	MOVL ecxArg+4(FP), CX
	CPUID
	MOVL AX, eax+8(FP)
	MOVL BX, ebx+12(FP)
	MOVL CX, ecx+16(FP)
	MOVL DX, edx+20(FP)
	RET

// func xgetbv() (eax, edx uint32)
TEXT ·xgetbv(SB), NOSPLIT, $0-8
	MOVL $0, CX
	XGETBV
	MOVL AX, eax+0(FP)
	MOVL DX, edx+4(FP)
	RET
